"use client";

import { motion } from "framer-motion";
import Link from "next/link";
import { ArrowRight } from "lucide-react";
import { cn } from "@/lib/utils";
import { services } from "@/data/services";
import { GetStartedButton } from "@/components/ui/get-started-button";
import { MagnetizeButton } from "../ui/magnetize-button";

export default function ServicesOverview() {
  return (
    <section className="section-spacing bg-background relative overflow-hidden">
      {/* Background accents */}
      <div className="absolute top-0 right-0 w-[600px] h-[600px] bg-primary/5 blur-[120px] rounded-full -mr-40 -mt-40" />

      <div className="container-fluid relative z-10">
        {/* Header */}
        <div className="max-w-3xl mb-16 md:mb-24 space-y-6">
          <motion.div
            initial={{ opacity: 0, x: -20 }}
            whileInView={{ opacity: 1, x: 0 }}
            viewport={{ once: true }}
            className="text-primary text-[10px] font-black uppercase tracking-[0.3em]"
          >
            Capabilities
          </motion.div>
          <motion.h2
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            className="h2 leading-[1.1]"
          >
            Premium Digital <span className="text-gradient">Services</span> <br className="hidden md:block" />
            Tailored for Scale.
          </motion.h2>
          <motion.p
            initial={{ opacity: 0, y: 20 }}
            whileInView={{ opacity: 1, y: 0 }}
            viewport={{ once: true }}
            transition={{ delay: 0.1 }}
            className="text-muted-foreground text-lg max-w-2xl leading-relaxed"
          >
            We don't just build, we engineer. From SaaS MVPs to complex cloud architectures,
            our collective delivers production-ready systems.
          </motion.p>
        </div>

        {/* Services Grid - Restored wrapper */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8 mb-16">
          {services.map((service, index) => (
            <motion.div
              key={service.id}
              initial={{ opacity: 0, y: 40 }}
              whileInView={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.6, delay: index * 0.1 }}
              viewport={{ once: true }}
            >
              <Link
                href={`/services/${service.id}`}
                className={cn(
                  "group relative flex flex-col items-start text-left",
                  "p-8 md:p-12 rounded-[2.5rem]",
                  "bg-card border border-border hover:border-primary/30",
                  "transition-all duration-500",
                  "hover:-translate-y-2 hover:shadow-premium dark:hover:shadow-glow",
                  "focus:outline-none focus:ring-2 focus:ring-primary/40"
                )}
              >
                <div className="w-16 h-16 mb-8 flex items-center justify-center rounded-2xl bg-primary/10 group-hover:bg-primary/20 transition-all duration-500">
                  <service.icon className="w-7 h-7 text-primary transition-transform group-hover:scale-110" />
                </div>

                <h3 className="text-2xl font-black text-foreground mb-4 tracking-tighter uppercase font-outfit">
                  {service.title}
                </h3>

                <p className="text-muted-foreground text-sm leading-relaxed mb-10 line-clamp-2">
                  {service.description}
                </p>

                <div className="flex flex-wrap gap-2 mb-10">
                  {service.features.slice(0, 2).map((feat) => (
                    <span key={feat} className="px-3 py-1 bg-background rounded-full border border-border text-[9px] font-black uppercase tracking-widest text-muted-foreground">
                      {feat}
                    </span>
                  ))}
                </div>

                <div className="mt-auto pt-8 border-t border-border w-full flex items-center justify-between group-hover:border-primary/20 transition-colors">
                  <span className="text-[10px] font-black uppercase tracking-widest text-primary">Details</span>
                  <ArrowRight className="w-4 h-4 text-primary group-hover:translate-x-1 transition-transform" />
                </div>
              </Link>
            </motion.div>
          ))}
        </div>

        {/* View All Links */}
        <div className="flex flex-col sm:flex-row items-center justify-between pt-16 border-t border-border/50 gap-8">
          <div className="text-center sm:text-left">
            <p className="text-xl font-black text-foreground mb-1 uppercase tracking-tighter">Ready to evolve?</p>
            <p className="text-muted-foreground text-sm">Schedule a free 15-minute engineering consult.</p>
          </div>

          <Link href="/services">
            <MagnetizeButton particleCount={14} className="h-16 px-10 rounded-2xl text-sm font-black uppercase tracking-widest">
              View All Services <ArrowRight className="ml-2 w-4 h-4" />
            </MagnetizeButton>
          </Link>
        </div>
      </div>
    </section>
  );
}