"use client";

import Link from "next/link";
import { motion } from "framer-motion";
import { ArrowRight, ExternalLink } from "lucide-react";
import { projects } from "@/data/projects";
import { cn } from "@/lib/utils";

export default function FeaturedProjects() {
  return (
    <section className="section-spacing bg-background relative overflow-hidden">
      <div className="container-fluid relative z-10">
        {/* Header */}
        <div className="flex flex-col md:flex-row justify-between items-start md:items-end mb-16 md:mb-24 gap-8">
          <div className="max-w-2xl">
            <motion.div
              initial={{ opacity: 0, x: -20 }}
              whileInView={{ opacity: 1, x: 0 }}
              viewport={{ once: true }}
              className="text-primary text-[10px] font-black uppercase tracking-[0.3em] mb-4"
            >
              Case Studies
            </motion.div>
            <h2 className="h2 tracking-tighter uppercase leading-[1.1]">
              Engineered <span className="text-gradient">Growth</span>.<br />
              <span className="italic font-light">Featured Work.</span>
            </h2>
          </div>
          <Link
            href="/projects"
            className="group flex items-center gap-2 text-primary font-black uppercase text-xs tracking-widest hover:gap-4 transition-all pb-2 border-b border-primary/20"
          >
            All Work <ArrowRight className="w-5 h-5" />
          </Link>
        </div>

        {/* Grid Restored - Forever Store, MediSync etc */}
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 lg:gap-20">
          {projects.slice(0, 4).map((project, index) => (
            <motion.div
              key={project.id}
              initial={{ opacity: 0, y: 40 }}
              whileInView={{ opacity: 1, y: 0 }}
              transition={{ delay: index * 0.1 }}
              viewport={{ once: true }}
              className="group relative"
            >
              <div className="relative aspect-[16/10] overflow-hidden rounded-[2.5rem] bg-card border border-border group-hover:border-primary/50 transition-all duration-700 shadow-sm hover:shadow-premium dark:hover:shadow-glow shine-effect">
                <img
                  src={project.thumbnail}
                  alt={project.title}
                  className="w-full h-full object-cover transition-transform duration-1000 group-hover:scale-105"
                />

                {/* Meta Overlays */}
                <div className="absolute top-8 left-8 right-8 flex justify-between items-start opacity-0 group-hover:opacity-100 transition-opacity duration-500">
                  <div className="px-4 py-2 bg-black/60 backdrop-blur-md rounded-full border border-white/10">
                    <span className="text-[10px] font-black uppercase tracking-widest text-white">{project.category}</span>
                  </div>
                  <div className="flex gap-2">
                    {project.tags.slice(0, 2).map(tag => (
                      <span key={tag} className="px-3 py-1.5 bg-white/10 backdrop-blur-md border border-white/10 rounded-full text-[9px] uppercase tracking-widest text-white/80 font-bold">
                        {tag}
                      </span>
                    ))}
                  </div>
                </div>

                <div className="absolute inset-0 bg-gradient-to-t from-black/90 via-transparent to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-500 flex items-end p-12">
                  <div className="space-y-4 translate-y-8 group-hover:translate-y-0 transition-transform duration-500">
                    <h3 className="text-3xl font-black text-white uppercase tracking-tighter">{project.title}</h3>
                    <div className="flex gap-6">
                      <Link href={`/projects/${project.slug}`} className="text-white text-[10px] font-black uppercase tracking-widest hover:text-primary transition-colors flex items-center gap-2">
                        Case Study <ArrowRight className="w-3 h-3" />
                      </Link>
                      {project.demoUrl && (
                        <Link href={project.demoUrl} target="_blank" className="text-white/60 text-[10px] font-black uppercase tracking-widest hover:text-white transition-colors flex items-center gap-2">
                          Live Preview <ExternalLink className="w-3 h-3" />
                        </Link>
                      )}
                    </div>
                  </div>
                </div>
              </div>

              {/* Visible description on mobile/natural flow */}
              <div className="mt-8 space-y-4">
                <div className="flex items-center justify-between">
                  <h4 className="text-xl font-bold uppercase tracking-tight text-foreground lg:hidden">{project.title}</h4>
                  <span className="text-[10px] font-bold text-muted-foreground uppercase tracking-widest lg:hidden">{project.category}</span>
                </div>
                <p className="text-muted-foreground text-sm leading-relaxed max-w-lg hidden lg:block group-hover:text-foreground transition-colors">
                  {project.description}
                </p>
              </div>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}
