"use client";

import { useState } from "react";
import Link from "next/link";
import { motion } from "framer-motion";
import { ChevronDown, ArrowRight } from "lucide-react";
import { cn } from "@/lib/utils";

const faqs = [
  {
    question: "What is your development process?",
    answer: "We follow a community-driven development framework that includes Discovery, Strategy, iterative Development (sprints), and rigorous Testing before deployment. Our focus is on scalability and performance from day one.",
  },
  {
    question: "Do you build MVPs for startups?",
    answer: "Yes, SaaS MVP development is one of our core specialties. We help founders validate ideas fast by building production-ready MVPs in 6-10 weeks.",
  },
  {
    question: "Which technologies do you use?",
    answer: "We primarily use Next.js, TypeScript, Tailwind CSS, and GSAP for the frontend. For the backend, we work with Node.js, MongoDB, PostgreSQL, and AWS/Vercel for hosting.",
  },
  {
    question: "How do you handle maintenance?",
    answer: "We offer ongoing support and maintenance packages to keep your application secure, updated, and performing at its peak long after the initial launch.",
  },
];

export default function FAQPreview() {
  const [openIndex, setOpenIndex] = useState<number | null>(0);

  return (
    <section className="section-spacing bg-background relative overflow-hidden border-t border-border/40">
      <div className="container-fluid relative z-10">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-20 lg:gap-32 items-start">
          {/* Left Column: Heading */}
          <div className="space-y-8 lg:sticky lg:top-32">
            <motion.div
              initial={{ opacity: 0, x: -20 }}
              whileInView={{ opacity: 1, x: 0 }}
              viewport={{ once: true }}
              className="text-primary text-[10px] font-black uppercase tracking-[0.3em]"
            >
              FAQ
            </motion.div>
            <h2 className="h2 tracking-tighter uppercase leading-[1.2]">
              Common <span className="text-gradient">Questions</span>.
            </h2>
            <p className="text-muted-foreground text-lg leading-relaxed max-w-md">
              Everything you need to know about working with our engineering collective
              and how we deliver results.
            </p>
            <Link
              href="/faq"
              className="inline-flex items-center gap-3 text-sm font-black uppercase tracking-widest text-foreground hover:text-primary transition-colors pt-4"
            >
              Still confused? Talk to us <ArrowRight className="w-5 h-5" />
            </Link>
          </div>

          {/* Right Column: Accordion */}
          <div className="space-y-4">
            {faqs.map((faq, index) => (
              <div
                key={index}
                className={cn(
                  "bg-card rounded-[2rem] overflow-hidden transition-all duration-500 border border-border shadow-sm",
                  openIndex === index ? "border-primary/30 shadow-premium" : "hover:border-primary/20"
                )}
              >
                <button
                  onClick={() => setOpenIndex(openIndex === index ? null : index)}
                  className="w-full p-8 md:p-10 flex items-center justify-between text-left group transition-all"
                  aria-expanded={openIndex === index}
                >
                  <span className={cn(
                    "text-lg md:text-xl font-black uppercase tracking-tight transition-colors font-outfit pr-4 leading-tight",
                    openIndex === index ? "text-primary" : "text-foreground group-hover:text-primary"
                  )}>
                    {faq.question}
                  </span>
                  <div className={cn(
                    "w-10 h-10 rounded-full flex items-center justify-center transition-all bg-primary/5 border border-border shrink-0",
                    openIndex === index ? "bg-primary text-white border-primary" : "text-muted-foreground"
                  )}>
                    <ChevronDown className={cn("w-5 h-5 transition-transform duration-300", openIndex === index ? "rotate-180" : "")} />
                  </div>
                </button>

                <div className={cn(
                  "overflow-hidden transition-all duration-300",
                  openIndex === index ? "max-h-[500px] opacity-100" : "max-h-0 opacity-0"
                )}>
                  <div className="p-8 md:p-10 pt-0 border-t border-border/50">
                    <p className="text-muted-foreground leading-relaxed text-sm md:text-base italic">
                      {faq.answer}
                    </p>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </section>
  );
}
