"use client";

import { motion } from "framer-motion";
import { Globe, ShieldCheck, Zap, Cpu } from "lucide-react";

const clientLogos = [
  { name: "Technoinnovators", icon: Globe, color: "text-blue-500" },
  { name: "FirmX", icon: Zap, color: "text-amber-500" },
  { name: "ElestroPlus", icon: Cpu, color: "text-emerald-500" },
  { name: "Elite Design", icon: Globe, color: "text-purple-500" },
  { name: "Huge Labs", icon: ShieldCheck, color: "text-red-500" },
];

export default function TrustSection() {
  return (
    <section className="section-spacing bg-background border-t border-border/40 transition-colors duration-500 overflow-hidden relative">
      <div className="container-fluid relative z-10">
        <div className="text-center mb-16">
          <h3 className="h3 text-muted-foreground uppercase tracking-[0.2em]">
            Trusted Everywhere
          </h3>
        </div>

        <div className="flex flex-wrap justify-center items-center gap-8 md:gap-16 lg:gap-24 opacity-40 hover:opacity-100 transition-opacity duration-500">
          {clientLogos.map((client) => (
            <motion.div
              key={client.name}
              whileHover={{ scale: 1.05 }}
              className="flex items-center gap-2 md:gap-3 transition-all cursor-pointer group"
            >
              <client.icon className={`w-6 h-6 md:w-8 md:h-8 ${client.color} transition-all group-hover:drop-shadow-[0_0_10px_rgba(var(--primary),0.2)]`} />
              <span className="text-lg md:text-2xl font-black text-foreground group-hover:text-primary dark:text-white/80 dark:group-hover:text-white tracking-tighter">
                {client.name}
              </span>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
}
