"use client";

import { useState, useEffect } from "react";
import { motion } from "framer-motion";
import Link from "next/link";
import { Star, Quote, Copy, Check, ExternalLink, ArrowRight } from "lucide-react";
import toast from "react-hot-toast";
import { cn } from "@/lib/utils";

const GOOGLE_REVIEW_URL = "https://g.page/r/YOUR_GOOGLE_REVIEW_LINK/review";

const reviews = [
  {
    id: 1,
    author: "Arjun Mehta",
    role: "Founder, TechStack",
    image: "https://i.pravatar.cc/150?u=1",
    rating: 5,
    text: "Webkaro transformed our MVP into a production-ready application in record time. Their attention to scalability and performance is unmatched.",
    date: "2 months ago",
  },
  {
    id: 2,
    author: "Sarah Jenkins",
    role: "Product Manager, Flow",
    image: "https://i.pravatar.cc/150?u=2",
    rating: 5,
    text: "The collaborative collective model works impressively well. We got access to specialized talent that moved our project forward significantly.",
    date: "1 month ago",
  },
  {
    id: 3,
    author: "Rahul Singh",
    role: "CEO, Sporty",
    image: "https://i.pravatar.cc/150?u=3",
    rating: 5,
    text: "Beautiful UI and rock-solid backend. The GSAP animations make our landing page feel premium and high-end. Highly recommended!",
    date: "3 weeks ago",
  },
  {
    id: 4,
    author: "Elena Rodriguez",
    role: "Director of Engineering",
    image: "https://i.pravatar.cc/150?u=4",
    rating: 5,
    text: "Cleanest codebase I've seen from an agency. Their use of TypeScript and modern architecture patterns saved us months of refactoring.",
    date: "2 weeks ago",
  },
];

export default function Testimonials() {
  const [isPaused, setIsPaused] = useState(false);

  return (
    <section className="section-spacing bg-background relative overflow-hidden border-t border-border/40">
      <div className="container-fluid relative z-10">
        <div className="text-center mb-16 md:mb-32 max-w-4xl mx-auto space-y-6">
          <motion.div
            initial={{ opacity: 0, scale: 0.9 }}
            whileInView={{ opacity: 1, scale: 1 }}
            className="inline-flex items-center gap-2 px-4 py-2 bg-primary/5 border border-primary/10 rounded-full"
          >
            <img src="https://upload.wikimedia.org/wikipedia/commons/c/c1/Google_%22G%22_logo.svg" alt="Google" className="w-4 h-4" />
            <span className="text-[10px] font-black uppercase tracking-[0.2em] text-foreground/60">Verified Reviews</span>
          </motion.div>
          <h2 className="h2 tracking-tighter uppercase leading-[1.2]">
            Trusted By <br className="hidden md:block" />
            <span className="text-gradient">Innovative</span> Teams.
          </h2>
        </div>

        {/* Infinite Scroll Wrapper restored */}
        <div
          className="relative w-full overflow-hidden mb-24"
          onMouseEnter={() => setIsPaused(true)}
          onMouseLeave={() => setIsPaused(false)}
        >
          <motion.div
            className="flex gap-8 w-max"
            animate={{
              x: isPaused ? 0 : ["0%", "-50%"],
            }}
            transition={{
              duration: 50,
              repeat: Infinity,
              ease: "linear",
              repeatType: "loop",
            }}
          >
            {[...reviews, ...reviews, ...reviews, ...reviews].map((review, idx) => (
              <div
                key={`${review.id}-${idx}`}
                className="flex-shrink-0 w-[320px] md:w-[480px] bg-card glass p-8 md:p-12 rounded-[3.5rem] border border-border hover:border-primary/40 transition-all duration-500 group"
              >
                <div className="flex justify-between items-start mb-10">
                  <div className="flex items-center gap-4">
                    <img
                      src={review.image}
                      className="w-12 h-12 md:w-16 md:h-16 rounded-2xl border border-border object-cover"
                      alt={review.author}
                    />
                    <div>
                      <h4 className="text-lg font-black uppercase tracking-tighter text-foreground">{review.author}</h4>
                      <p className="text-[9px] uppercase tracking-widest font-black text-muted-foreground">{review.role}</p>
                    </div>
                  </div>
                  <div className="flex gap-0.5">
                    {[...Array(review.rating)].map((_, i) => (
                      <Star key={i} className="w-3 h-3 md:w-4 md:h-4 fill-amber-400 text-amber-400" />
                    ))}
                  </div>
                </div>
                <div className="relative">
                  <Quote className="w-12 h-12 text-primary/5 absolute -left-4 -top-8 -z-10 rotate-180" />
                  <p className="text-lg md:text-xl font-bold font-outfit leading-relaxed italic relative z-10 text-foreground/90">
                    "{review.text}"
                  </p>
                </div>
              </div>
            ))}
          </motion.div>
        </div>

        {/* CTA Block */}
        <div className="max-w-4xl mx-auto">
          <div className="bg-primary/5 border border-primary/20 p-10 md:p-20 rounded-[4rem] text-center space-y-10 relative overflow-hidden group">
            <div className="absolute top-0 right-0 w-64 h-64 bg-primary/10 blur-[100px] rounded-full -mr-32 -mt-32 transition-all group-hover:bg-primary/20" />

            <p className="text-2xl md:text-3xl font-black text-foreground uppercase tracking-tighter leading-tight relative z-10">
              Supporting us helps our collective <span className="italic font-light">thrive</span>.
            </p>

            <div className="flex flex-col sm:flex-row items-center justify-center gap-6 relative z-10">
              <Link
                href={GOOGLE_REVIEW_URL}
                target="_blank"
                className="h-16 px-10 rounded-2xl bg-foreground text-background font-black flex items-center justify-center gap-3 hover:scale-105 transition-transform"
              >
                Write Google Review <ExternalLink className="w-4 h-4" />
              </Link>
              <button
                className="h-16 px-10 rounded-2xl border border-border font-black flex items-center justify-center gap-3 hover:bg-white/5 transition-colors"
              >
                Our Portfolio <ArrowRight className="w-4 h-4" />
              </button>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
}
